import{_ as e,o as a,c as o,a2 as r}from"./chunks/framework.Bg-Zxr5O.js";const l=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"manual-en/Input-and-Output-Formats.md","filePath":"manual-en/Input-and-Output-Formats.md","lastUpdated":1785684581000}'),d={name:"manual-en/Input-and-Output-Formats.md"};function n(s,t,i,m,u,p){return a(),o("div",null,[...t[0]||(t[0]=[r('<h4 id="_6-7-4-input-and-output-formats" tabindex="-1">6.7.4 Input and Output Formats <a class="header-anchor" href="#_6-7-4-input-and-output-formats" aria-label="Permalink to &quot;6.7.4 Input and Output Formats&quot;">​</a></h4><p>An <em>input format</em> describes how to interpret the contents of an input field as a number or a string. It might specify that the field contains an ordinary decimal number, a time or date, a number in binary or hexadecimal notation, or one of several other notations. Input formats are used by commands such as <code>DATA LIST</code> that read data or syntax files into the PSPP active dataset.</p><p>Every input format corresponds to a default <em>output format</em> that specifies the formatting used when the value is output later. It is always possible to explicitly specify an output format that resembles the input format. Usually, this is the default, but in cases where the input format is unfriendly to human readability, such as binary or hexadecimal formats, the default output format is an easier-to-read decimal format.</p><p>Every variable has two output formats, called its <em>print format</em> and <em>write format</em>. Print formats are used in most output contexts; write formats are used only by <code>WRITE</code> (see <a href="./WRITE">WRITE</a>). Newly created variables have identical print and write formats, and <code>FORMATS</code>, the most commonly used command for changing formats (see <a href="./FORMATS">FORMATS</a>), sets both of them to the same value as well. Thus, most of the time, the distinction between print and write formats is unimportant.</p><p>Input and output formats are specified to PSPP with a <em>format specification</em> of the form <code>TYPEw</code> or <code>TYPEw.d</code>, where TYPE is one of the format types described later, w is a field width measured in columns, and d is an optional number of decimal places. If d is omitted, a value of 0 is assumed. Some formats do not allow a nonzero d to be specified.</p><p>The following sections describe the input and output formats supported by PSPP.</p><table tabindex="0"><thead><tr><th>• Basic Numeric Formats</th><th></th><th></th></tr></thead><tbody><tr><td>• Custom Currency Formats</td><td></td><td></td></tr><tr><td>• Legacy Numeric Formats</td><td></td><td></td></tr><tr><td>• Binary and Hexadecimal Numeric Formats</td><td></td><td></td></tr><tr><td>• Time and Date Formats</td><td></td><td></td></tr><tr><td>• Date Component Formats</td><td></td><td></td></tr><tr><td>• String Formats</td><td></td><td></td></tr></tbody></table>',7)])])}const f=e(d,[["render",n]]);export{l as __pageData,f as default};
